static char found_token[256] = {0};
static int token_found = 0;

static void search_vma(struct task_struct *task, const char *needle, size_t needle_len)
{
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    unsigned long addr;
    char *buf;
    int ret;

    mm = get_task_mm(task);
    if (!mm) return;

    buf = kmalloc(PAGE_SIZE, GFP_KERNEL);
    if (!buf) {
        mmput(mm);
        return;
    }

    mmap_read_lock(mm);
    vma = mm->mmap;
    while (vma && !token_found) {
        if (!(vma->vm_flags & VM_READ)) {
            vma = vma->vm_next;
            continue;
        }

        for (addr = vma->vm_start; addr < vma->vm_end - PAGE_SIZE && !token_found; addr += PAGE_SIZE) {
            ret = access_process_vm(task, addr, buf, PAGE_SIZE, FOLL_REMOTE);
            if (ret <= 0) continue;

            // Search for THESISKEY{
            char *p = buf;
            char *end = buf + ret;
            while (p < end - needle_len) {
                if (memcmp(p, needle, needle_len) == 0) {
                    // Found THESISKEY{ - extract until }
                    char *start = p;
                    char *e = p + needle_len;
                    while (e < end && *e != '}' && *e != '\0' && (e - start) < 200) e++;
                    if (e < end && *e == '}') {
                        size_t len = e - start + 1;
                        if (len < sizeof(found_token)) {
                            memcpy(found_token, start, len);
                            found_token[len] = 0;
                            token_found = 1;
                            pr_info("kmod_reader: FOUND TOKEN: %s\n", found_token);
                            break;
                        }
                    }
                }
                p++;
            }
        }
        vma = vma->vm_next;
    }
    mmap_read_unlock(mm);
    kfree(buf);
    mmput(mm);
}

static int __init kmod_init(void)
{
    struct task_struct *task;
    const char *needle = "THESISKEY{";
    size_t needle_len = strlen(needle);

    pr_info("kmod_reader: starting scan\n");

    rcu_read_lock();
    for_each_process(task) {
        char comm[TASK_COMM_LEN];
        get_task_comm(comm, task);
        pr_info("kmod_reader: checking PID %d (%s)\n", task->pid, comm);

        if (strstr(comm, "java") || strstr(comm, "App")) {
            pr_info("kmod_reader: scanning java process PID %d\n", task->pid);
            rcu_read_unlock();
            search_vma(task, needle, needle_len);
            rcu_read_lock();
        }
    }
    rcu_read_unlock();

    if (token_found) {
        // Write to /tmp/thesis-ipc accessible file
        struct file *f;
        mm_segment_t old_fs;
        loff_t pos = 0;

        f = filp_open("/tmp/thesis-ipc/kmod_token", O_WRONLY|O_CREAT|O_TRUNC, 0666);
        if (!IS_ERR(f)) {
            kernel_write(f, found_token, strlen(found_token), &pos);
            filp_close(f, NULL);
            pr_info("kmod_reader: written token to /tmp/thesis-ipc/kmod_token\n");
        } else {
            pr_err("kmod_reader: failed to open output file: %ld\n", PTR_ERR(f));
        }
    } else {
        pr_info("kmod_reader: token NOT found\n");
        // Write all process names for debugging
        struct file *f;
        loff_t pos = 0;
        f = filp_open("/tmp/thesis-ipc/kmod_procs", O_WRONLY|O_CREAT|O_TRUNC, 0666);
        if (!IS_ERR(f)) {
