                kernel_write(f, line, strlen(line), &pos);
            }
            rcu_read_unlock();
            filp_close(f, NULL);
        }
    }

    return 0;
}

static void __exit kmod_exit(void)
{
    pr_info("kmod_reader: unloaded\n");
}

module_init(kmod_init);
module_exit(kmod_exit);
