            for (i = 0; i + needle_len < (size_t)ret && !token_found; i++) {
                if (memcmp(buf + i, needle, needle_len) == 0) {
                    size_t j = i + needle_len;
                    while (j < (size_t)ret && buf[j] != '}' && buf[j] != '\0' && (j - i) < 200)
                        j++;
                    if (j < (size_t)ret && buf[j] == '}') {
                        size_t tlen = j - i + 1;
                        if (tlen < sizeof(found_token)) {
