            get_task_comm(comm, task);
            n = snprintf(line, sizeof(line), "PID %d: %s\n", task->pid, comm);
            kernel_write(f, line, n, &pos);
        }
        rcu_read_unlock();
        filp_close(f, NULL);
    }

    return 0;
}

